package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct { // 01 TEMP-REC, 8 bytes
	TcSensor string          // PIC X(4) @0 len=4
	TcF      decimal.Decimal // PIC 9(3)V9 @4 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"               // PIC X len=1 = "N"
var WsC decimal.Decimal = decimal.New(0, 0) // PIC S9(3)V99 len=5 = 0
var WsFreeze int64 = 0                   // PIC 99 len=2 = 0
var WsCount int64 = 0                    // PIC 99 len=2 = 0
var WsFEd string                         // PIC ZZ9.9 len=5
var WsCEd string                         // PIC -ZZ9.99 len=7

var tempRec TempRec

var allLines []string
var lineIdx int

func isInputDone() bool { return WsEofFlag == "Y" }

func pow10(n int) decimal.Decimal {
	return decimal.New(1, int32(n))
}

// store for S9(3)V99 : 3 integer digits, 2 decimals
func storeWsC(d decimal.Decimal) decimal.Decimal {
	scale := int32(2)
	intDigits := 3
	powTotal := pow10(intDigits + int(scale)) // 10^5 = 100000
	scaled := d.Shift(scale)                  // *100
	if scaled.IsZero() {
		return decimal.Zero
	}
	isNeg := scaled.Sign() < 0
	absScaled := scaled.Abs().Truncate(0)
	rem := absScaled.Mod(powTotal)
	if rem.IsZero() {
		return decimal.Zero
	}
	if isNeg {
		rem = rem.Neg()
	}
	return rem.Shift(-scale)
}

func storePic99(v int64) int64 {
	// keep low-order 2 digits
	m := v % 100
	if m < 0 {
		m += 100
	}
	return m
}

func formatZZ9Dot9(v decimal.Decimal) string {
	intDigits := 3
	fracDigits := 1
	zCount := 2
	absVal := v.Abs()
	// integer part raw
	intPartRaw := absVal.Truncate(0)
	powInt := pow10(intDigits)
	intMod := intPartRaw.Mod(powInt)
	// build int string zero padded
	intModInt := intMod.IntPart() // fits in 0..999
	intStr := fmt.Sprintf("%0*d", intDigits, intModInt)
	// Z suppression
	intChars := []byte(intStr)
	suppressed := true
	for i := 0; i < intDigits; i++ {
		isZ := i < zCount
		ch := intChars[i]
		if isZ && suppressed && ch == '0' {
			intChars[i] = ' '
		} else {
			if ch != '0' {
				suppressed = false
			}
			// keep char as is (for mandatory 9, zero stays)
			if !isZ {
				suppressed = false
			}
		}
	}
	// fractional part
	frac := absVal.Sub(intPartRaw) // 0.xxx
	fracShifted := frac.Shift(int32(fracDigits)).Truncate(0)
	fracInt := fracShifted.IntPart()
	fracStr := fmt.Sprintf("%0*d", fracDigits, fracInt)
	return string(intChars) + "." + fracStr
}

func formatMinusZZ9Dot99(v decimal.Decimal) string {
	intDigits := 3
	fracDigits := 2
	zCount := 2
	signChar := byte(' ')
	if v.Sign() < 0 && !v.IsZero() {
		signChar = '-'
	}
	absVal := v.Abs()
	intPartRaw := absVal.Truncate(0)
	powInt := pow10(intDigits)
	intMod := intPartRaw.Mod(powInt)
	intModInt := intMod.IntPart()
	intStr := fmt.Sprintf("%0*d", intDigits, intModInt)
	intChars := []byte(intStr)
	suppressed := true
	for i := 0; i < intDigits; i++ {
		isZ := i < zCount
		ch := intChars[i]
		if isZ && suppressed && ch == '0' {
			intChars[i] = ' '
		} else {
			if ch != '0' {
				suppressed = false
			}
			if !isZ {
				suppressed = false
			}
		}
	}
	frac := absVal.Sub(intPartRaw)
	fracShifted := frac.Shift(int32(fracDigits)).Truncate(0)
	fracInt := fracShifted.IntPart()
	fracStr := fmt.Sprintf("%0*d", fracDigits, fracInt)
	return string([]byte{signChar}) + string(intChars) + "." + fracStr
}

func loadInput() {
	f, err := os.Open("input.dat")
	if err != nil {
		allLines = nil
		return
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	// allow long lines
	buf := make([]byte, 0, 64*1024)
	sc.Buffer(buf, 10*1024*1024)
	for sc.Scan() {
		line := sc.Text()
		// Scanner strips \n and \r; if file used \r\n, \r remains? Text() strips \r? Actually SplitLines removes \r.
		// Keep line as is (without newline)
		allLines = append(allLines, line)
	}
}

func parseTempRec(line string) TempRec {
	// pad with spaces to 8
	if len(line) < 8 {
		line = line + strings.Repeat(" ", 8-len(line))
	} else if len(line) > 8 {
		line = line[:8]
	}
	sensor := line[0:4]
	fField := line[4:8]
	// parse numeric field 9(3)V9 : 4 digits
	// if field contains spaces, treat as zero for those positions
	trimmed := strings.TrimSpace(fField)
	var d decimal.Decimal
	if trimmed == "" {
		d = decimal.Zero
	} else {
		// collect digits; if any non-digit, treat as 0? but spec digits only
		// we try to parse integer of digits
		// remove spaces
		digits := ""
		for _, c := range fField {
			if c >= '0' && c <= '9' {
				digits += string(c)
			} else if c == ' ' {
				// treat space as 0? COBOL would treat blank as 0? Keep as '0' for position
				// we replace space with '0' to keep length? Usually leading spaces => 0.
				digits += "0"
			}
		}
		if digits == "" {
			d = decimal.Zero
		} else {
			// parse
			var iv int64
			for _, c := range digits {
				iv = iv*10 + int64(c-'0')
			}
			d = decimal.New(iv, -1)
		}
	}
	return TempRec{TcSensor: sensor, TcF: d}
}

// Paragraphs

func mainPara() {
	loadInput()
	lineIdx = 0
	readPara()
	for !isInputDone() {
		processPara()
	}
	// CLOSE TEMP-FILE (no action)
	// DISPLAY "READINGS: " WS-COUNT " BELOW ZERO: " WS-FREEZE
	cntStr := fmt.Sprintf("%02d", storePic99(WsCount))
	frzStr := fmt.Sprintf("%02d", storePic99(WsFreeze))
	fmt.Printf("READINGS: %s BELOW ZERO: %s\n", cntStr, frzStr)
}

func readPara() {
	if lineIdx >= len(allLines) {
		WsEofFlag = "Y"
		return
	}
	tempRec = parseTempRec(allLines[lineIdx])
	lineIdx++
}

func processPara() {
	// COMPUTE WS-C ROUNDED = (TC-F - 32) * 5 / 9
	base := tempRec.TcF.Sub(decimal.NewFromInt(32))
	mul := base.Mul(decimal.NewFromInt(5))
	// divide by 9
	div := mul.Div(decimal.NewFromInt(9))
	rounded := div.Round(2) // half away from zero
	WsC = storeWsC(rounded)

	if WsC.Sign() < 0 {
		WsFreeze = storePic99(WsFreeze + 1)
	}
	WsCount = storePic99(WsCount + 1)

	WsFEd = formatZZ9Dot9(tempRec.TcF)
	WsCEd = formatMinusZZ9Dot99(WsC)

	// DISPLAY TC-SENSOR " " WS-F-ED "F " WS-C-ED "C"
	fmt.Printf("%s %sF %sC\n", tempRec.TcSensor, WsFEd, WsCEd)

	readPara()
}

func main() {
	mainPara()
}
